from generators.common import contrast_text, rotate_hue


def render(c: dict[str, str], source_path: str) -> str:
    recording = c.get("recording") or rotate_hue(c["accent_start"], 90, saturation_scale=1.12, lightness_scale=1.02)
    transcribing = c.get("transcribing") or rotate_hue(c["accent_end"], 210, saturation_scale=0.92, lightness_scale=1.04)

    return f"""pragma Singleton
import QtQuick
import Quickshell

// Auto-generated by .config/theme/scripts/generate_theme.py (do not edit by hand)
// Source: {source_path}
Singleton {{
    readonly property color base: "{c['base']}"
    readonly property color crust: "{c['crust']}"
    readonly property color text: "{c['text']}"
    readonly property color overlay1: "{c['overlay1']}"
    readonly property color peach: "{c['peach']}"
    readonly property color gradStart: "{c['accent_start']}"
    readonly property color gradEnd: "{c['accent_end']}"
    readonly property color textLeft: "{c['accent_text_left']}"
    readonly property color textRight: "{c['accent_text_right']}"
    readonly property color recording: "{recording}"
    readonly property color recordingText: "{contrast_text(recording, dark=c['crust'], light=c['text'])}"
    readonly property color transcribing: "{transcribing}"
    readonly property color transcribingText: "{contrast_text(transcribing, dark=c['crust'], light=c['text'])}"
    readonly property color waiting: "{c['red']}"
    readonly property color asking: "{c['peach']}"
    readonly property color done: "{c['terminal_green']}"
    readonly property string font: "JetBrainsMono Nerd Font"
}}
"""
